(()=>{const g=window.__game;g.G.state='play';g.clearSoldiers();g.LIFE.test=true;g.lifeReset();g.P.x=-175;g.P.z=-322;g.P.yaw=-Math.PI/2;g.setViewMode(false);g.lifeUpdate(1/30);for(let k=0;k<3;k++)g.trySpawnYard();g.lifeSpawnN(12);;g.sim(120,1/30);let best=null,bn=-1;for(const c of g.civs){if(!c.alive)continue;let n=0;for(const o of g.civs)if(o.alive&&Math.hypot(o.x-c.x,o.z-c.z)<13)n+=1+(o.yard||o.drive||o.dog>=0?.6:0);if(n>bn){bn=n;best=c;}}
 if(best){const L=best.L;let dx=L?L.dx:1,dz=L?L.dz:0;if(best.yard||best.drive){dx=-(best.yard?best.yard.nx:0)||dx;dz=-(best.yard?best.yard.nz:0)||dz;}let ok=false;for(const sg of [1,-1,.7,-.7]){const px=best.x+dx*11*sg+(-dz)*2.5,pz=best.z+dz*11*sg+dx*2.5;if(g.freeSpot(px,pz)){g.P.x=px;g.P.z=pz;ok=true;break;}}
  g.P.yaw=Math.atan2(-(best.x-g.P.x),-(best.z-g.P.z));g.P.pitch=-.05;for(const c of g.civs){c.scared=false;}} g.setViewMode(false);g.sim(2,1/30);const r={civs:g.civs.length,roles:g.civs.map(c=>c.role+':'+c.st+':'+Math.round(Math.hypot(c.x-g.P.x,c.z-g.P.z))),cars:g.traffic.filter(c=>c.on).map(c=>[Math.round(c.x),Math.round(c.z),+c.spd.toFixed(1)]),yaw:+g.P.yaw.toFixed(2)};g.G.state='pause';document.getElementById('menu').hidden=true;document.getElementById('hud').hidden=true;return r;})()

